cards.extra:
echo '== imports'; I=$(go list -e -overlay $P/overlay.json -f '{{join .Imports " "}}' ./control) || exit 1; for i in $I; do case $i in context|encoding/json|errors|net/http|time|morphstudio/queue|morphstudio/github|morphstudio/eventlog|morphstudio/session) ;; *) echo "imports: package control imports $i (allowed: context, encoding/json, errors, net/http, time, morphstudio/queue, morphstudio/github, morphstudio/eventlog, morphstudio/session)"; exit 1;; esac; done
echo '== clock'; C=$(gofmt -l -r 'time.Now -> time.Time' control/control.go 2>&1)$(gofmt -l -r 'time.Since -> time.Time' control/control.go 2>&1); [ -z "$C" ] || { echo "clock: control/control.go reads time.Now or time.Since (the clock is the now argument)"; exit 1; }
echo '== net'; for x in http.DefaultClient http.Get http.Post http.PostForm http.Head; do C=$(gofmt -l -r "$x -> http.NoBody" control/control.go 2>&1); [ -z "$C" ] || { echo "net: control/control.go uses $x (every HTTP call goes through the injected Do)"; exit 1; }; done
